/// <summary>
/// Created for the FSD - CB201 Rebates Extension - Undertake Build -  External Data Sources
/// </summary>
public class METExternalSellDataCleanupService extends SysOperationServiceBase
{
}

Method.Source:
/// <summary>
/// Process the cleanup.
/// </summary>
/// <param name = "_dataContract"></param>
[SysEntryPointAttribute]
public void processOperation(METExternalSellDataCleanupContract _dataContract)
{
    System.Exception ex;
    #OCCRetryCount

    Query                       query               = _dataContract.getQuery();
    QueryRun                    queryRun            = new QueryRun(query);
    METRebateScanSupplierTable  externalSellData;

    try
    {
        while (queryRun.next())
        {
            externalSellData = QueryRun.get(tableNum(METRebateScanSupplierTable));

            ttsbegin;
            externalSellData.selectForUpdate(true);
            externalSellData.delete();
            ttscommit;
        }
    }
    catch (Exception::Deadlock)
    {
        retry;
    }

    catch (Exception::UpdateConflict)
    {
        if (appl.ttsLevel() == 0)
        {
            if (xSession::currentRetryCount() >= #RetryNum)
            {
                throw Exception::UpdateConflictNotRecovered;
            }
            else
            {
                retry;
            }
        }
        else
        {
            throw Exception::UpdateConflict;
        }
    }

    catch (Exception::Error)
    {
        error(strFmt("@RET102"));
        retry;
    }

    catch (Exception::CLRError)
    {
        ex = ClrInterop::getLastException();

        if (ex != null)
        {
            ex = ex.get_InnerException();
            if (ex != null)
            {
                error(strFmt("@RET102"));
            }
        }

        retry;
    }
}
